-- CLS visible DB suite, independently authored from the frozen CLS-001..040 contract.
-- No proposed feature migration, feature implementation, app suite or holdout was read.
-- 083000 category prelude must already be committed and applied by CI; no 55P04 waiver.
-- 085000 supplies the three shared primitives; 140000 supplies classes.
-- Real competing-connection evidence is separately mandatory after CI (see handoff).
begin;
set local role postgres;
set local search_path = extensions, public;
select set_config('request.jwt.claims', '', true);
select plan(710);

create function pg_temp.u(n integer) returns uuid language sql immutable as
$$ select ('74000000-0000-4000-8000-' || lpad(to_hex(n),12,'0'))::uuid $$;
create function pg_temp.claim(who integer, gym integer default 1, extra jsonb default '{}'::jsonb)
returns void language plpgsql as $$
declare r text; j jsonb;
begin
  r := case who when 21 then 'gym_owner' when 22 then 'gym_manager'
    when 23 then 'front_desk' when 24 then 'trainer' when 25 then 'trainer'
    when 26 then 'front_desk' when 27 then 'gym_owner'
    when 28 then 'super_admin' when 29 then 'platform_support' else 'member' end;
  j := jsonb_build_object('sub',pg_temp.u(who+900),'role','authenticated',
    'app_role',r,'tenant_id',pg_temp.u(gym));
  if who between 21 and 27 then j := j || jsonb_build_object('staff_id',pg_temp.u(who));
  elsif who >= 101 then j := j || jsonb_build_object('member_id',pg_temp.u(who)); end if;
  perform set_config('request.jwt.claims',(j || extra)::text,true);
end $$;
-- Exceptions are captured in a subtransaction: a refusal cannot leave writes behind.
create function pg_temp.run(q text) returns text language plpgsql as $$
begin execute q; return 'OK'; exception when others then return sqlstate; end $$;
create table pg_temp.saved(k text primary key, v jsonb);
grant all on pg_temp.saved to authenticated;
create function pg_temp.capture(p_key text,p_query text) returns text language plpgsql as $$
declare v_result jsonb;
begin execute 'select to_jsonb(x) from (' || p_query || ') x' into v_result;
  insert into pg_temp.saved values(p_key,v_result) on conflict(k) do update set v=excluded.v;
  return 'OK'; exception when others then return sqlstate; end $$;
create function pg_temp.id(p_key text,p_field text) returns uuid language sql stable as
$$ select (v->>p_field)::uuid from pg_temp.saved where saved.k=p_key $$;

select enum_has_labels('public','booking_status',array['booked','cancelled_by_member','cancelled_by_gym','session_cancelled','attended','no_show']::name[],'BOOKING: canonical six statuses in order');
select enum_has_labels('public','class_session_status',array['scheduled','cancelled']::name[],'CLS: canonical session statuses');
select enum_has_labels('public','message_category',array['renewal','payment','fulfilment','promotion','motivation','class_update','announcement']::name[],'Prelude: committed transactional class_update before announcement');
select is(pg_temp.run($$select app.booking_lock(pg_temp.u(1),'invalid',pg_temp.u(301))$$),'22023','BOOKING: lock kind validation');
select is(pg_temp.run($$select app.booking_lock(pg_temp.u(1),'class_session',pg_temp.u(301))$$),'OK','BOOKING: class lock accepted');
select is(pg_temp.run($$select app.booking_lock(pg_temp.u(1),'trainer_slot',pg_temp.u(301))$$),'OK','BOOKING: PT lock accepted');
select ok(exists(select 1 from pg_locks where pid=pg_backend_pid() and locktype='advisory' and granted and mode='ExclusiveLock'),'BOOKING: real transaction holds an advisory lock');
select is((select count(distinct hashtextextended('booking:'||t||':'||k||':'||r,0))::integer from (values(pg_temp.u(1),'class_session',pg_temp.u(301)),(pg_temp.u(2),'class_session',pg_temp.u(301)),(pg_temp.u(1),'trainer_slot',pg_temp.u(301)),(pg_temp.u(1),'class_session',pg_temp.u(302))) x(t,k,r)),4,'BOOKING: tenant, kind and resource isolate canonical lock keys');
select is(app.class_local_instant('America/New_York',date '2026-03-08',time '02:30'),timestamptz '2026-03-08 07:30+00','CLS-026: spring gap follows PostgreSQL AT TIME ZONE');
select is(app.class_local_instant('America/New_York',date '2026-11-01',time '01:30'),timestamptz '2026-11-01 06:30+00','CLS-026: autumn fold chooses standard time');

