-- Full state-machine matrix and identity immutability are appended below.

-- Catalogue presence, grants, RLS, all declared composite FKs and trigger shapes.
select has_table('public','services','CLS-021: services exists');
select ok((select relrowsecurity from pg_class where oid=to_regclass('public.services')),'CLS-021: services RLS enabled');
select is((select count(*)::integer from pg_policy where polrelid=to_regclass('public.services')),2,'CLS-021: services exactly two read policies');
select ok(has_table_privilege('authenticated','public.services','SELECT') and not has_table_privilege('authenticated','public.services','INSERT,UPDATE,DELETE'),'CLS-021: services select-only grant');
select ok(not has_table_privilege('anon','public.services','SELECT,INSERT,UPDATE,DELETE'),'CLS-021: services no anon access');
select has_table('public','class_rules','CLS-021: class_rules exists');
select ok((select relrowsecurity from pg_class where oid=to_regclass('public.class_rules')),'CLS-021: class_rules RLS enabled');
select is((select count(*)::integer from pg_policy where polrelid=to_regclass('public.class_rules')),2,'CLS-021: class_rules exactly two read policies');
select ok(has_table_privilege('authenticated','public.class_rules','SELECT') and not has_table_privilege('authenticated','public.class_rules','INSERT,UPDATE,DELETE'),'CLS-021: class_rules select-only grant');
select ok(not has_table_privilege('anon','public.class_rules','SELECT,INSERT,UPDATE,DELETE'),'CLS-021: class_rules no anon access');
select ok(exists(select 1 from pg_constraint c where c.conrelid=to_regclass('public.class_rules') and c.conname='class_rules_service_id_fkey' and c.contype='f' and c.confrelid=to_regclass('public.services') and c.confdeltype='a' and (select array_agg(a.attname::text order by x.ord) from unnest(c.conkey) with ordinality x(n,ord) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=x.n)=array['tenant_id','service_id']),'CLS-025: class_rules.service_id composite restrictive FK');
select ok(exists(select 1 from pg_constraint c where c.conrelid=to_regclass('public.class_rules') and c.conname='class_rules_branch_id_fkey' and c.contype='f' and c.confrelid=to_regclass('public.branches') and c.confdeltype='a' and (select array_agg(a.attname::text order by x.ord) from unnest(c.conkey) with ordinality x(n,ord) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=x.n)=array['tenant_id','branch_id']),'CLS-025: class_rules.branch_id composite restrictive FK');
select ok(exists(select 1 from pg_constraint c where c.conrelid=to_regclass('public.class_rules') and c.conname='class_rules_trainer_staff_id_fkey' and c.contype='f' and c.confrelid=to_regclass('public.staff') and c.confdeltype='a' and (select array_agg(a.attname::text order by x.ord) from unnest(c.conkey) with ordinality x(n,ord) join pg_attribute a on a.attrelid=c.conrelid and a.attnum=x.n)=array['tenant_id','trainer_staff_id']),'CLS-025: class_rules.trainer_staff_id composite restrictive FK');
select has_table('public','class_sessions','CLS-021: class_sessions exists');
select ok((select relrowsecurity from pg_class where oid=to_regclass('public.class_sessions')),'CLS-021: class_sessions RLS enabled');
select is((select count(*)::integer from pg_policy where polrelid=to_regclass('public.class_sessions')),2,'CLS-021: class_sessions exactly two read policies');
select ok(has_table_privilege('authenticated','public.class_sessions','SELECT') and not has_table_privilege('authenticated','public.class_sessions','INSERT,UPDATE,DELETE'),'CLS-021: class_sessions select-only grant');
