insert into public.qr_sessions(id,tenant_id,branch_id,token_hash,gate_mode,expires_at) values(pg_temp.u(15001),pg_temp.u(1),pg_temp.u(11),repeat('74',32),'rotating_screen',statement_timestamp()+interval '1 day');
create function pg_temp.checkin_live(m uuid) returns boolean language plpgsql as $f$
begin
  begin
    insert into public.attendance(tenant_id,member_id,branch_id,source,qr_session_id) values(pg_temp.u(1),m,pg_temp.u(11),'qr',pg_temp.u(15001));
    raise exception 'parity rollback' using errcode='Z7401';
  exception when sqlstate 'Z7401' then return true;
    when sqlstate 'GL013' then return false;
  end;
end $f$;
-- Rollback-only historical-null fixture seam: only the dated CHECK is absent.
-- All helper and actual check-in probes below run with normal origin triggers.
create temp table classes_historical_date_check as
select pg_get_constraintdef(oid) as original_definition
from pg_constraint where conrelid='public.memberships'::regclass
 and conname='memberships_dated_unless_pending_chk';
alter table public.memberships drop constraint memberships_dated_unless_pending_chk;
