-- Remove only the newly imported parity membership rows before restoring the CHECK.
-- GL045 guards direct membership writes; this import cleanup is the sole replica block.
set local session_replication_role = replica;
delete from public.memberships where tenant_id=pg_temp.u(1)
 and id in (select pg_temp.u(n) from generate_series(17001,17030) n);
set local session_replication_role = origin;
do $$declare original text; begin
 select original_definition into strict original from classes_historical_date_check;
 execute 'alter table public.memberships add constraint memberships_dated_unless_pending_chk '||original;
end$$;
select is((select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.memberships'::regclass and conname='memberships_dated_unless_pending_chk'),(select original_definition from classes_historical_date_check),'CLS-013: historical fixture restores exact dated CHECK');
select ok((select convalidated from pg_constraint where conrelid='public.memberships'::regclass and conname='memberships_dated_unless_pending_chk'),'CLS-013: restored dated CHECK validated');
select is(current_setting('session_replication_role'),'origin','CLS-013: parity cleanup restores normal triggers');

-- Member read surface: exact output contract, counts only and own-booking privacy.
set local role postgres;
select is((select array_agg(a.n order by a.ord) from pg_proc p cross join lateral unnest(p.proargnames,p.proargmodes) with ordinality a(n,m,ord) where p.oid=to_regprocedure('public.read_member_class_schedule(date,date)') and a.m='t'),array['session_id','service_id','service_name','service_description','branch_id','branch_name','timezone','session_date','starts_at','ends_at','trainer_name','capacity','booked_count','spots_left','session_status','my_booking_id','my_booking_status','availability','can_cancel','cancel_by']::text[],'CLS-022: exact counts-only output has no other-person or trainer identifier');
set local role authenticated;
select pg_temp.claim(101);
select is(pg_temp.capture('privacy',$$select coalesce(jsonb_agg(to_jsonb(x)),'[]') as rows from public.read_member_class_schedule(current_date,current_date+27)x$$),'OK','CLS-022: complete member schedule');
select ok((select position(pg_temp.u(102)::text in v::text)=0 and position('Secret CLS member' in v::text)=0 and position('+91740000' in v::text)=0 and position(pg_temp.u(24)::text in v::text)=0 from pg_temp.saved where k='privacy'),'CLS-022: returned values contain no other member ID/name/phone or trainer ID');
select is((select count(*)::integer from public.read_class_timetable(null,current_date,current_date+27)),0,'CLS-023: member invoker timetable zero rows');
select is((select count(*)::integer from public.read_class_roster(pg_temp.u(302))),0,'CLS-023: member invoker roster zero rows');
select is(pg_temp.run($$select public.read_member_class_schedule(null,current_date)$$),'22023','CLS-022: null from refused');
select is(pg_temp.run($$select public.read_member_class_schedule(current_date,null)$$),'22023','CLS-022: null to refused');
select is(pg_temp.run($$select public.read_member_class_schedule(current_date+1,current_date)$$),'22023','CLS-022: reversed interval refused');
select is(pg_temp.run($$select public.read_member_class_schedule(current_date,current_date+31)$$),'22023','CLS-022: 32 inclusive days refused');
select is(pg_temp.run($$select public.read_member_class_schedule(current_date,current_date+30)$$),'OK','CLS-022: 31 inclusive days accepted');
select is((select count(*)::integer from public.read_member_class_schedule(current_date,current_date+27) where branch_id=pg_temp.u(12)),0,'CLS-022: home branch visibility by default');
set local role postgres;
update public.organization_settings set class_allow_cross_branch=true where tenant_id=pg_temp.u(1);
set local role authenticated;
select pg_temp.claim(101);
select ok(exists(select 1 from public.read_member_class_schedule(current_date,current_date+27) where session_id=pg_temp.u(306)),'CLS-022: cross-branch setting exposes other own-gym branch');
select is(pg_temp.run($$select public.book_class_session(pg_temp.u(306))$$),'OK','CLS-012: current cross-branch setting allows booking');
set local role postgres;
update public.organization_settings set class_allow_cross_branch=false where tenant_id=pg_temp.u(1);
select pg_temp.claim(24);
set local role authenticated;
select ok(exists(select 1 from public.read_class_roster(pg_temp.u(302)) where member_id=pg_temp.u(102) and membership_live),'CLS-023: trainer reads another session roster with frozen membership flag');
select pg_temp.claim(21,1,jsonb_build_object('impersonation_session_id',pg_temp.u(999)));
select ok(exists(select 1 from public.read_class_timetable(null,current_date,current_date+27)),'CLS-024: support-preview staff reads remain available');

