-- Capacity reduction preserves seats and reports zero left, without overriding the lock.
set local role postgres;
insert into public.class_sessions(id,tenant_id,service_id,branch_id,session_date,starts_at,ends_at,capacity,trainer_staff_id)
 values(pg_temp.u(903),pg_temp.u(1),pg_temp.id('service','id'),pg_temp.u(11),(statement_timestamp()+interval '6 days' at time zone 'Asia/Kolkata')::date,statement_timestamp()+interval '6 days',statement_timestamp()+interval '6 days 1 hour',2,pg_temp.u(24));
set local role authenticated;
select pg_temp.claim(101);
select is(pg_temp.run($$select public.book_class_session(pg_temp.u(903))$$),'OK','CLS-014: first capacity fixture seat');
select pg_temp.claim(102);
select is(pg_temp.run($$select public.book_class_session(pg_temp.u(903))$$),'OK','CLS-014: second capacity fixture seat');
select pg_temp.claim(21);
select is(pg_temp.run($$select public.update_class_session(pg_temp.u(903),(select session_date from public.class_sessions where id=pg_temp.u(903)),(select(starts_at at time zone 'Asia/Kolkata')::time from public.class_sessions where id=pg_temp.u(903)),60,1,pg_temp.u(24))$$),'OK','CLS-009: capacity may fall below held count');
set local role postgres;
select is(app.class_holding_count(pg_temp.u(1),pg_temp.u(903)),2,'CLS-009: reduction preserves both commitments');
select ok((select customised_at is not null from public.class_sessions where id=pg_temp.u(903)),'CLS-009: individual edit detaches propagation');
set local role authenticated;
select pg_temp.claim(104);
select is(pg_temp.run($$select public.book_class_session(pg_temp.u(903))$$),'GL090','CLS-014: reduction refuses new seats');
select is((select spots_left from public.read_member_class_schedule(current_date,current_date+27) where session_id=pg_temp.u(903)),0,'CLS-022: spots left floors at zero');
select is((select availability from public.read_member_class_schedule(current_date,current_date+27) where session_id=pg_temp.u(903)),'full','CLS-022: reduced capacity full state');
set local role postgres;
select is(pg_temp.run($$insert into public.class_bookings(tenant_id,session_id,member_id) values(pg_temp.u(1),pg_temp.u(903),pg_temp.u(101))$$),'23505','CLS-014: unique duplicate booking backstop');
select is(pg_temp.run($$insert into public.class_bookings(tenant_id,session_id,member_id) values(pg_temp.u(1),pg_temp.u(310),pg_temp.u(104))$$),'23503','CLS-025: booking session composite FK');
select is(pg_temp.run($$insert into public.class_bookings(tenant_id,session_id,member_id) values(pg_temp.u(1),pg_temp.u(903),pg_temp.u(110))$$),'23503','CLS-025: booking member composite FK');

