-- Branch-local generation at opposite date extremes, timezone fallback, overlap advisory.
set local role authenticated;
select pg_temp.claim(21);
select is(pg_temp.capture('westrule',$$select * from public.create_class_rules(pg_temp.id('service','id'),pg_temp.u(12),array[extract(dow from (statement_timestamp() at time zone 'Etc/GMT+12')::date+1)::smallint],time '23:30',60,2,null,(statement_timestamp() at time zone 'Etc/GMT+12')::date+1,null)$$),'OK','CLS-026: western-extreme local rule');
select pg_temp.claim(27,2);
select is(pg_temp.capture('eastrule',$$select * from public.create_class_rules(pg_temp.u(201),pg_temp.u(13),array[extract(dow from (statement_timestamp() at time zone 'Pacific/Kiritimati')::date+1)::smallint],time '00:30',60,2,null,(statement_timestamp() at time zone 'Pacific/Kiritimati')::date+1,null)$$),'OK','CLS-026: eastern-extreme local rule');
set local role postgres;
select ok(not exists(select 1 from public.class_sessions where rule_id=pg_temp.id('westrule','rule_id') and (session_date<>(starts_at at time zone 'Etc/GMT+12')::date or starts_at<>(session_date+time '23:30') at time zone 'Etc/GMT+12' or session_date<(statement_timestamp() at time zone 'Etc/GMT+12')::date or session_date>(statement_timestamp() at time zone 'Etc/GMT+12')::date+27)),'CLS-026: west midnight-crossing occurrence belongs to start day in local horizon');
select ok(not exists(select 1 from public.class_sessions where rule_id=pg_temp.id('eastrule','rule_id') and (session_date<>(starts_at at time zone 'Pacific/Kiritimati')::date or starts_at<>(session_date+time '00:30') at time zone 'Pacific/Kiritimati' or session_date<(statement_timestamp() at time zone 'Pacific/Kiritimati')::date or session_date>(statement_timestamp() at time zone 'Pacific/Kiritimati')::date+27)),'CLS-026: east occurrence belongs to branch day in local horizon');
select ok(exists(select 1 from public.class_sessions where rule_id=pg_temp.id('westrule','rule_id')) and exists(select 1 from public.class_sessions where rule_id=pg_temp.id('eastrule','rule_id')),'CLS-026: extreme timezone assertions are non-vacuous');
update public.branches set timezone='Invalid/CLS74' where id=pg_temp.u(12);
select is(app.class_branch_timezone(pg_temp.u(1),pg_temp.u(12)),'Asia/Kolkata','CLS-026: invalid branch zone falls back to valid gym zone');
update public.organizations set timezone='Invalid/CLS74' where id=pg_temp.u(1);
select is(app.class_branch_timezone(pg_temp.u(1),pg_temp.u(12)),'UTC','CLS-026: both invalid zones fall back to UTC');
update public.organizations set timezone='Asia/Kolkata' where id=pg_temp.u(1);
update public.branches set timezone='Etc/GMT+12' where id=pg_temp.u(12);
set local role authenticated;
select pg_temp.claim(21);
select is(pg_temp.capture('overlapone',$$select public.create_class_session(pg_temp.id('service','id'),pg_temp.u(11),(statement_timestamp() at time zone 'Asia/Kolkata')::date+7,time '18:00',60,2,pg_temp.u(24)) as id$$),'OK','CLS-008: one-off with eligible trainer');
select is(pg_temp.capture('overlaptwo',$$select public.create_class_session(pg_temp.id('service','id'),pg_temp.u(11),(statement_timestamp() at time zone 'Asia/Kolkata')::date+7,time '18:30',60,2,pg_temp.u(24)) as id$$),'OK','CLS-023: overlap advisory, never GL096');
select is((select trainer_overlaps from public.read_class_timetable(null,current_date,current_date+27) where session_id=pg_temp.id('overlapone','id')),true,'CLS-023: overlapping trainer flag');
select is(pg_temp.run($$select public.create_class_session(pg_temp.id('service','id'),pg_temp.u(11),(statement_timestamp() at time zone 'Asia/Kolkata')::date+7,time '18:00',60,2,pg_temp.u(24))$$),'23505','CLS-008: one-off scheduled slot unique');
select is(pg_temp.run($$select public.create_class_session(pg_temp.id('service','id'),pg_temp.u(11),(statement_timestamp() at time zone 'Asia/Kolkata')::date+28,time '18:00',60,2,null)$$),'22023','CLS-008: one-off beyond horizon');
select is(pg_temp.run($$select public.create_class_session(pg_temp.id('service','id'),pg_temp.u(11),(statement_timestamp() at time zone 'Asia/Kolkata')::date-1,time '18:00',60,2,null)$$),'22023','CLS-008: one-off before today');
select is(pg_temp.run($$select public.cancel_class_session(pg_temp.id('overlapone','id'),' x ')$$),'22023','CLS-010: reason trimmed minimum length');
select is(pg_temp.run($$select public.cancel_class_session(pg_temp.id('overlapone','id'),repeat('x',201))$$),'22023','CLS-010: reason maximum length');
select is(pg_temp.run($$select public.cancel_class_session(pg_temp.id('overlapone','id'),'Instructor unwell')$$),'OK','CLS-010: cancel empty session');
select is(pg_temp.run($$select public.update_class_session(pg_temp.id('overlapone','id'),current_date+7,time '18:00',60,2,null)$$),'GL111','CLS-009: cancelled one-off editing refused');
